function home(){return header()+`<main><section class="home-layout"><div class="intro"><div class="eyebrow">${t().tag}</div><h1>${t().headline}</h1><p>${t().intro}</p>${btn((p().game&&!p().game.finished?t().resume:t().play)+ico('arrow'),'play','primary')}<div class="home-modes">${btn(t().adventure,'adventure','secondary')}${btn(t().free,'free','secondary')}</div><p class="home-meta">${ico('leaf')}${window.PikoClub?.active?t().offline:window.PikoAds?(family.lang==='pl'?'Gra działa offline · reklamy wymagają internetu':'Play offline · ads need internet'):t().offline}</p></div><div class="hero-art"><div class="blob"></div><div class="spark">✦</div><div class="hero-tag">${t().little}</div><div class="hero-board"><div>${img(world().symbols[0])}</div><div>${img(world().symbols[1])}</div><div>${img(world().symbols[1])}</div><div class="empty">?</div></div>${img(world().symbols[2],'floating-art')}<div class="hero-foot">2 × 2 → 3 × 3 → 4 × 4 → 6 × 6 → ★ 9 × 9</div></div></section><section class="home-worlds"><div class="section-head"><h2>${t().choose}</h2>${btn(t().all+' ↗','worlds','textbtn')}</div><div class="world-grid">${D.worlds.slice(0,6).map(worldCard).join('')}</div></section><footer class="home-bottom">${btn(ico('album')+t().album,'album','textbtn')}${btn('★ '+t().badges,'badges','textbtn')}${btn(ico('lock')+t().parents,'parents','textbtn')}</footer></main>`;}
