function adventure(){const master=p().size===9,w=world();return header(t().missions)+`<main class="narrow"><div class="eyebrow">${name(w)} · ${p().size} × ${p().size}</div><h1 class="page-title">${master?L('★ Wyprawy mistrza','★ Master adventures'):L('Odkryj swój świat','Discover your world')}</h1><p class="subcopy">${story(w.id)} ${L('Każda wyprawa to trzy małe kroki.','Each adventure has three small steps.')} ★ ${p().stars} ${t().stars}</p>${btn(L('Zmień wielkość planszy','Change grid size'),'stages','textbtn')}<div class="mission-map">${Array.from({length:6},(_,c)=>{const done=P.chapterDone(p(),w.id,master,c),open=P.available(p(),w.id,master,c),count=Array.from({length:3},(_,s)=>P.stageKey(w.id,master,c,s)).filter(k=>p().missions.includes(k)).length;return `<button class="mission-card ${done?'mission-done':''}" data-action="mission" data-chapter="${c}" ${open?'':'disabled'}>${img(w.symbols[c])}<span><b>${c+1}. ${esc(w.symbols[c][family.lang])}</b><small>${done?L('Wyprawa ukończona — zagraj ponownie','Adventure completed — play again'):open?L('Odnalezione ślady','Discovered clues'):L('Najpierw poprzednia wyprawa','Finish the previous adventure')} · ${count}/3 ★</small></span></button>`;}).join('')}</div></main>`;}
function badgeName(id){if(id==='first')return L('Pierwsza układanka','First puzzle');if(id==='master-ten')return L('Dziesięć wyzwań 9×9','Ten 9×9 challenges');if(id.startsWith('size-'))return L('Pierwsze ','First ')+id.slice(5)+'×'+id.slice(5);const w=D.worlds.find(w=>id.endsWith('-'+w.id));return (id.startsWith('album-')?L('Kolekcjoner: ','Collector: '):L('Odkrywca: ','Explorer: '))+(w?name(w):'');}
function badges(){const ids=['first','size-4','size-6','size-9','master-ten',...D.worlds.flatMap(w=>['trip-'+w.id,'album-'+w.id])];return header(t().badges)+`<main><h1 class="page-title">${t().badges}</h1><p class="subcopy">★ ${p().stars} ${t().stars} · ${L('Pomoc nie odbiera nagród. Każdy ma swoje tempo.','Hints never take rewards away. Play at your own pace.')}</p><div class="badge-grid">${ids.map(id=>{const earned=p().badges.includes(id);return `<article class="badge-card ${earned?'earned':''}"><span aria-hidden="true">${earned?'★':'☆'}</span><h2>${badgeName(id)}</h2><p>${earned?L('Zdobyta!','Earned!'):id==='master-ten'?L('Ukończ 10 różnych plansz 9×9.','Complete 10 different 9×9 puzzles.'):id.startsWith('album-')?L('Zbierz 6 obrazków w tym świecie.','Collect 6 pictures in this world.'):id.startsWith('trip-')?L('Ukończ jedną wyprawę w tym świecie.','Complete one adventure in this world.'):L('Ukończ pierwszą planszę tego rodzaju.','Complete your first puzzle of this kind.')}</p></article>`;}).join('')}</div></main>`;}
