function game(){const a=p().game,b=q(),n=b.size,shape=E.blocks[n];let related=selected>=0?E.groups(n).filter(g=>g.cells.includes(selected)).flatMap(g=>g.cells):[];if(hint)related=(hint.groups||[]).flatMap(g=>g.cells);if(clash)related=clash.cells;
const cell=(i,large=false)=>{const v=a.values[i],r=Math.floor(i/n),c=i%n,notes=a.notes?.[i]||[];const cl=['cell',b.given[i]?'given':'',selected===i?'selected':'',related.includes(i)?'related':'',selected>=0&&v&&v===a.values[selected]?'same-symbol':'',hint?.cell===i?'target':'',clash&&(i===selected||i===clash.other)?'conflict':'',shape&&(c+1)%shape[1]===0&&c<n-1?'br':'',shape&&(r+1)%shape[0]===0&&r<n-1?'bb':''].filter(Boolean).join(' ');return `<button class="${cl}" data-action="cell" data-cell="${i}" tabindex="${large||selected===i||(selected<0&&i===0)?0:-1}" aria-label="${t().row} ${r+1}, ${t().col} ${c+1}, ${v?esc(symbol(v)[family.lang]):t().empty}${b.given[i]?', '+t().given:''}${notes.length?', '+t().notes+': '+notes.map(v=>esc(symbol(v)[family.lang])).join(', '):''}" aria-pressed="${selected===i}">${v?img(symbol(v)):notes.length?'<span class="cell-notes">'+Array.from({length:9},(_,j)=>notes.includes(j+1)?img(symbol(j+1)):'<i></i>').join('')+'</span>':''}</button>`;};
const blockOrigin=selected>=0?Math.floor(Math.floor(selected/n)/3)*3*n+Math.floor((selected%n)/3)*3:0;
const board=`<div class="board-wrap small${n}"><div class="game-heading"><span class="step">${a.mission?L('Etap ','Stage ')+(a.mission.step+1)+'/3':t().puzzle+' '+b.order} · ${n} × ${n}</span><span class="step">${a.values.filter(Boolean).length}/${n*n}</span></div><div class="board ${zoomed&&n===9?'overview':''}" role="group" aria-label="Sudoku ${n} × ${n}" style="--n:${n}">${a.values.map((_,i)=>cell(i)).join('')}</div>${n===9?btn(zoomed?t().zoomOff:t().zoom,'zoom','secondary zoom-button',`aria-pressed="${zoomed}"`):''}${zoomed&&n===9?`<p class="zoom-caption">${L('Dotknij planszy powyżej, aby wybrać inny blok.','Tap the board above to choose another box.')}</p><div class="block-selector">${Array.from({length:9},(_,k)=>btn(L('Blok ','Box ')+(k+1),'block','secondary',`data-block="${k}" aria-pressed="${blockOrigin===Math.floor(k/3)*27+(k%3)*3}"`)).join('')}</div><div class="board zoom-block" style="--n:3" role="group" aria-label="${L('Powiększony blok','Enlarged box')}">${Array.from({length:9},(_,j)=>cell(blockOrigin+Math.floor(j/3)*n+j%3,true)).join('')}</div>`:''}<div class="board-hint">${ico('lock')}${t().fixed}</div></div>`;
return header(name(world()),t().stages[sizes.indexOf(n)])+`<main class="game-layout"><div>${a.mission?`<aside class="mission-scene"><p>${story(world().id)} · ${a.mission.step}/3</p>${Array.from({length:3},(_,i)=>img(world().symbols[(a.mission.chapter+i)%9],i<a.mission.step?'':'undiscovered')).join('')}</aside>`:''}${board}</div><div class="game-side"><div class="eyebrow">${n} × ${n}</div><h2>${t().stages[sizes.indexOf(n)]}</h2><p class="subcopy">${t().tap}</p>${n===9?btn((noteMode?'✓ ':'')+t().notes,'notes','secondary',`aria-pressed="${noteMode}"`):''}<div class="palette" data-n="${n}" style="--n:${n}">${Array.from({length:n},(_,i)=>btn(img(symbol(i+1)),'symbol','',`data-value="${i+1}" aria-label="${esc(symbol(i+1)[family.lang])}"`)).join('')}</div><div class="tools">${btn(ico('undo')+t().undo,'undo','tool',a.history.length?'':'disabled')}${btn(ico('erase')+t().erase,'erase','tool',selected>=0&&!b.given[selected]&&(a.values[selected]||a.notes?.[selected]?.length)?'':'disabled')}${btn(ico('hint')+t().hint,'hint','tool help')}</div><div class="feedback ${bad?'bad':''}" role="status">${esc(message||t().tap)}</div>${hint?hintPanel():''}${btn(t().rules,'rules','textbtn small-link')}</div></main>`;}
function hintPanel(){let text=t().look;if(hint.repair)text=t().repair;else if(hint.stage>=2){text=t()[hint.kind==='missing'?'missing':hint.kind==='single'?'single':hint.kind==='hidden'?'hidden':'showOnly'];if(hint.kind==='single'&&q().size<4)text=family.lang==='pl'?'Sprawdź wiersz i kolumnę. Pasuje tu tylko:':'Check the row and column. Only this picture fits:';}
return `<aside class="hint-panel"><header><span>${t().hintTitle}${hint.repair?'':` · ${hint.stage}/3`}</span>${btn(ico('close'),'closeHint','textbtn',`aria-label="${t().close}"`)}</header><p>${text}</p>${!hint.repair&&hint.stage>=2&&hint.kind!=='show'?`<div class="hint-row">${img(symbol(hint.value))}<b>${esc(symbol(hint.value)[family.lang])}</b></div>`:''}${btn(hint.repair?t().repairBtn:hint.stage<2?t().moreClue:t().show,hint.repair?'repair':'hintNext','secondary')}</aside>`;}
function result(){const a=p().game,b=q(),recent=p().recent.slice(-5),suggest=b.size<9&&(b.size===2?recent.filter(x=>x.size===2&&!x.assisted).length>=3:recent.filter(x=>x.size===b.size&&!x.assisted).length>=4),breakDue=family.settings.reminder&&sessionSeconds>=family.settings.reminder*60;
return header()+`<main class="result">${img(world().symbols[award?Math.max(0,(p().album[p().world]||1)-1):0],'result-art')}<span class="result-badge">${ico(award?'star':'check')}${award?t().newSticker:t().progress}</span><h1>${t().success}</h1><p class="reward-line">${a.isNew?'★ +1 · ':''}${p().stars} ${t().stars}</p>${newBadges.map(id=>`<p class="badge-unlock">★ ${badgeName(id)}</p>`).join('')}<p>${breakDue?t().breakTime:a.isNew?t().successBody:t().replay}</p><div class="stack">${btn(breakDue?t().done:a.mission&&a.mission.step===2?L('Wyprawa ukończona! Wróć na mapę','Adventure complete! Back to map'):t().next,breakDue?'home':'next','primary')}${btn(breakDue?t().next:t().done,breakDue?'next':'home','secondary')}${suggest?btn(t().suggest+' '+ico('arrow'),'bigger','textbtn'):''}${btn(ico('album')+t().album,'album','textbtn')}</div>${window.PikoAds&&!window.PikoClub?.active?`<div class="ad-controls"><span>${family.lang==='pl'?'Reklama':'Advertisement'}</span>${btn(family.lang==='pl'?'Zamknij reklamę':'Close ad','closeAd','secondary')}</div>`:''}</main>`;}
function album(){return header(t().album)+`<main><h1 class="page-title">${t().albumTitle}</h1><p class="subcopy">${t().albumSub}</p><div class="album-grid">${D.worlds.map(w=>{const count=p().album[w.id]||0;return `<section class="album-card"><h3>${name(w)}</h3><small>${count}/6 · ${count===6?L('Komplet!','Complete!'):L('Do obrazka: ','Next picture: ')+(3-(p().worldCounts[w.id]||0)%3)}</small><div class="stickers">${w.symbols.slice(0,6).map((s,i)=>`<div class="sticker ${i<count?'':'locked'}" aria-label="${i<count?esc(s[family.lang]):t().albumEmpty}">${i<count?img(s):'<span aria-hidden="true">✧</span>'}</div>`).join('')}</div></section>`}).join('')}</div></main>`;}
function profiles(){return header(t().profilesTitle)+`<main class="narrow"><h1 class="page-title">${t().profilesTitle}</h1><p class="subcopy">${t().profilesSub}</p><div class="profile-list">${family.profiles.map((pr,i)=>`<button class="profile-option ${family.active===i?'active':''}" data-action="profile" data-id="${i}">${img(avatar(i))}<span><b>${t().profile} ${i+1}</b><small>${t().solved}: ${pr.completed.length}</small></span></button>`).join('')}${family.profiles.length<3?btn('+ '+t().addProfile,'addProfile'):''}</div></main>`;}
